-- GeoStats v16.2.6: complete first-principles resolution of all 791 durable legacy rejections.
-- A cleared legacy veto never activates a category; normal source/integrity/editorial/playability gates still apply.
begin;
select pg_advisory_xact_lock(hashtext('geostats-v16.2.6-full-legacy-reaudit'));

on conflict(legacy_key) do update set
 source_line=excluded.source_line, category_title=excluded.category_title, legacy_source=excluded.legacy_source,
 legacy_domain_series=excluded.legacy_domain_series, historical_integrity_status=excluded.historical_integrity_status,
 historical_quality=excluded.historical_quality, editorial_disposition=excluded.editorial_disposition,
 legacy_guard_action=excluded.legacy_guard_action, reason_class=excluded.reason_class,
 first_principles_rationale=excluded.first_principles_rationale, recommended_next_action=excluded.recommended_next_action,
 linked_tracker_ids=excluded.linked_tracker_ids, linked_tracker_dispositions=excluded.linked_tracker_dispositions, reviewed_at=now();

update public.legacy_category_rejections_v16_2_6 r
set default_decision=case a.legacy_guard_action when 'clear_generic_legacy_block' then 'cleared_for_reconsideration' else 'confirmed_exclusion' end,
    required_action=a.recommended_next_action
from public.legacy_rejection_first_principles_reaudit_v16_2_6 a where a.legacy_key=r.legacy_key;

update public.legacy_rejection_semantic_aliases_v16_2_6 s
set review_status=case a.legacy_guard_action when 'clear_generic_legacy_block' then 'cleared' else 'confirmed_exclusion' end,
    rationale=concat(s.rationale,' | Full-791 v16.2.6 review: ',a.first_principles_rationale)
from public.legacy_rejection_first_principles_reaudit_v16_2_6 a where a.legacy_key=s.legacy_key;

update public.tracker_legacy_rejection_collisions_v16_2_6 c
set reaudit_disposition=a.editorial_disposition, reaudit_guard_action=a.legacy_guard_action
from public.legacy_rejection_first_principles_reaudit_v16_2_6 a where a.source_line=c.legacy_source_line;

-- Fail closed if any durable legacy row somehow lacks a final current decision.
do $$ begin
 if exists (select 1 from public.legacy_category_rejections_v16_2_6 where default_decision='requires_reaudit') then
  raise exception 'v16.2.6 full legacy re-audit incomplete: requires_reaudit rows remain';
 end if;
end $$;
commit;
